from pathlib import Path
import base64,json,subprocess
r=Path("/home/cat/projects/RK3576/rk3576_multimodal_stage5_review")
p=r/'tools/stage5_05_voice_run.py'
assert not p.exists()
with p.open("xb") as f:f.write(base64.b64decode(''))
p=r/'reports/stage5_05_board/thermal_matrix_entry.py'
assert not p.exists()
with p.open("xb") as f:f.write(base64.b64decode(''))
build=json.loads((r/'reports/stage5_05_board/build_thermal/result.json').read_text());assert build['successful']
log=r/'reports/stage5_05_board/thermal_matrix_launcher.log'
with log.open('xb') as out:
 child=subprocess.Popen(['python3','-I','-B',str(r/'reports/stage5_05_board/thermal_matrix_entry.py')],stdin=subprocess.DEVNULL,stdout=out,stderr=subprocess.STDOUT,start_new_session=True)
with (r/'reports/stage5_05_board/thermal_matrix_pid.json').open('x') as out:json.dump({'pid':child.pid,'script':str(r/'reports/stage5_05_board/thermal_matrix_entry.py')},out)
print('THERMAL_MATRIX_STARTED',child.pid,flush=True)
